INSERT INTO `creature_template_model` (`CreatureID`, `Idx`, `CreatureDisplayID`, `DisplayScale`, `Probability`, `VerifiedBuild`)
SELECT ct.`entry`, 0, 11686, 1, 1, 0 FROM `creature_template` ct
LEFT JOIN `creature_template_model` m ON m.`CreatureID` = ct.`entry` WHERE m.`CreatureID` IS NULL;

-- 3) BANDERAS: la misma regla de `sv_2026_09_19_03` (máscaras calculadas del header
--    `UNIT_FLAG*_ALLOWED`), por regla y sin lista de ids.
UPDATE `creature_template` SET
  `unit_flags`  = `unit_flags`  & 33563456,
  `unit_flags2` = `unit_flags2` & 67323939,
  `unit_flags3` = `unit_flags3` & 21881014
WHERE (`unit_flags`  & ~33563456) <> 0
   OR (`unit_flags2` & ~67323939) <> 0
   OR (`unit_flags3` & ~21881014) <> 0;

